//! The permission matrix document is what the expectations file renders (PLAN 3.2, R7).
//!
//! `docs/permission-matrix.md` is generated by `cargo xtask matrix`, and the `contracts` job of CI runs `cargo xtask matrix
//! --check`. This test is the same comparison without the toolchain around it, so that a change of the oracle that forgets the
//! document fails `cargo nextest run` too.

use davhaven_testkit::Expectations;
use davhaven_testkit::report::permission_matrix;

#[test]
fn the_committed_report_is_what_the_expectations_render() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/permission-matrix.md");
    let committed = std::fs::read_to_string(path).unwrap();
    let rendered = permission_matrix(&Expectations::bundled().unwrap()).unwrap();
    let first_difference = committed
        .lines()
        .zip(rendered.lines())
        .position(|(left, right)| left != right)
        .map_or_else(|| "the lengths differ".to_owned(), |line| format!("line {}", line + 1));
    assert!(
        committed == rendered,
        "docs/permission-matrix.md is out of date ({first_difference}); run `cargo xtask matrix` and commit the result"
    );
}
